      "/lib/server/audit/index.ts": "import { db } from '$lib/server/db';\nimport { auditLogs } from './schema';\nimport { desc, eq, and } from 'drizzle-orm';\n\n/**\n * SvelteForge audit trail (#232) — append-only business action logging.\n *\n *   await audit.record({\n *     actorId: user.id,\n *     action: 'punch.corrected',\n *     entityType: 'punch',\n *     entityId: punch.id,\n *     metadata: { before: { time: oldTime }, after: { time: newTime }, reason }\n *   });\n *\n * Reads:\n *   await audit.forEntity('punch', punchId);\n *   await audit.byActor(userId, { limit: 50 });\n */\n\nexport interface AuditEntryInput {\n\tactorId?: string | null;\n\taction: string;\n\tentityType: string;\n\tentityId?: string | null;\n\tmetadata?: Record<string, unknown>;\n\tipAddress?: string | null;\n\tuserAgent?: string | null;\n}\n\nexport interface AuditListOptions {\n\tlimit?: number;\n\toffset?: number;\n}\n\nexport interface AuditFilters extends AuditListOptions {\n\taction?: string;\n\tentityType?: string;\n}\n\nexport const audit = {\n\t/** Append an audit entry. Never updates/deletes existing rows. */\n\tasync record(input: AuditEntryInput): Promise<typeof auditLogs.$inferSelect> {\n\t\tconst [row] = await db\n\t\t\t.insert(auditLogs)\n\t\t\t.values({\n\t\t\t\tactorId: input.actorId ?? null,\n\t\t\t\taction: input.action,\n\t\t\t\tentityType: input.entityType,\n\t\t\t\tentityId: input.entityId ?? null,\n\t\t\t\tmetadata: input.metadata ?? {},\n\t\t\t\tipAddress: input.ipAddress ?? null,\n\t\t\t\tuserAgent: input.userAgent ?? null,\n\t\t\t\tcreatedAt: new Date()\n\t\t\t})\n\t\t\t.returning();\n\t\treturn row;\n\t},\n\n\t/** Full history for one entity (newest first). */\n\tasync forEntity(entityType: string, entityId: string, opts: AuditListOptions = {}): Promise<typeof auditLogs.$inferSelect[]> {\n\t\treturn db\n\t\t\t.select()\n\t\t\t.from(auditLogs)\n\t\t\t.where(and(eq(auditLogs.entityType, entityType), eq(auditLogs.entityId, entityId)))\n\t\t\t.orderBy(desc(auditLogs.createdAt))\n\t\t\t.limit(opts.limit ?? 50)\n\t\t\t.offset(opts.offset ?? 0);\n\t},\n\n\t/** Actions by one actor (newest first). */\n\tasync byActor(actorId: string, opts: AuditListOptions = {}): Promise<typeof auditLogs.$inferSelect[]> {\n\t\treturn db\n\t\t\t.select()\n\t\t\t.from(auditLogs)\n\t\t\t.where(eq(auditLogs.actorId, actorId))\n\t\t\t.orderBy(desc(auditLogs.createdAt))\n\t\t\t.limit(opts.limit ?? 50)\n\t\t\t.offset(opts.offset ?? 0);\n\t},\n\n\t/** Recent actions with optional filters (admin view). */\n\tasync list(filters: AuditFilters = {}): Promise<typeof auditLogs.$inferSelect[]> {\n\t\tconst conditions = [];\n\t\tif (filters.action) conditions.push(eq(auditLogs.action, filters.action));\n\t\tif (filters.entityType) conditions.push(eq(auditLogs.entityType, filters.entityType));\n\t\tconst where = conditions.length ? and(...conditions) : undefined;\n\t\tconst q = db.select().from(auditLogs);\n\t\tif (where) q.where(where);\n\t\treturn q.orderBy(desc(auditLogs.createdAt)).limit(filters.limit ?? 50).offset(filters.offset ?? 0);\n\t}\n};\n",
      "/lib/server/audit/pagination.ts": "/**\n * Audit pagination parsing (#297).\n *\n * Pure helper (no $lib imports) so it is unit-testable from the repo root:\n * `limit` is clamped to the explicit 1..100 range (default 50) and `offset`\n * to >= 0 (default 0). A negative limit must never reach the query layer\n * (LIMIT -10 is invalid SQL); non-numeric or out-of-range values fall back.\n */\nexport function parsePagination(\n\tsearchParams: URLSearchParams\n): { limit: number; offset: number } {\n\tconst rawLimit = searchParams.get('limit');\n\tconst parsedLimit = rawLimit === null || rawLimit === '' ? NaN : Number(rawLimit);\n\t// Clamp to the explicit 1..100 range: negative/zero values are clamped up\n\t// to 1, over-max values are clamped down to 100, missing/non-numeric\n\t// values fall back to the 50 default. A negative LIMIT can never reach\n\t// the query layer.\n\tconst limit = Number.isNaN(parsedLimit) ? 50 : Math.min(100, Math.max(1, Math.trunc(parsedLimit)));\n\tconst rawOffset = searchParams.get('offset');\n\tconst parsedOffset = rawOffset === null || rawOffset === '' ? NaN : Number(rawOffset);\n\tconst offset = Number.isNaN(parsedOffset) ? 0 : Math.max(0, Math.trunc(parsedOffset));\n\treturn { limit, offset };\n}\n",
      "/lib/server/audit/schema.ts": "import { pgTable, uuid, text, jsonb, timestamp } from 'drizzle-orm/pg-core';\n\n/**\n * Audit log schema (#232) — append-only at the application level.\n * There is NO update/delete path exposed by the API.\n *\n * `metadata` is for structured context (before/after, reason). NEVER store:\n * passwords, tokens, full object dumps of sensitive data, PII beyond what the\n * feature genuinely needs. See README.\n */\nexport const auditLogs = pgTable('audit_logs', {\n\tid: uuid('id').primaryKey().defaultRandom(),\n\tactorId: text('actor_id'), // nullable → system action\n\taction: text('action').notNull(),\n\tentityType: text('entity_type').notNull(),\n\tentityId: text('entity_id'),\n\tmetadata: jsonb('metadata').$type<Record<string, unknown>>(),\n\tipAddress: text('ip_address'),\n\tuserAgent: text('user_agent'),\n\tcreatedAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow()\n});\n",
      "/routes/(app)/admin/audit/+page.server.ts": "import { isAdmin } from '$lib/server/admin';\nimport { audit } from '$lib/server/audit';\nimport { parsePagination } from '$lib/server/audit/pagination';\nimport { error, type RequestEvent } from '@sveltejs/kit';\nimport type { PageServerLoad } from './$types';\n\n/** Admin guard (same pattern as the other admin pages). */\nasync function requireAdmin(event: RequestEvent): Promise<string> {\n\tif (!event.locals.user) {\n\t\tthrow error(401, { message: 'Authentication required' });\n\t}\n\tif (!(await isAdmin(event.locals.user.id))) {\n\t\tthrow error(403, { message: 'Admin access required' });\n\t}\n\treturn event.locals.user.id;\n}\n\nexport const load: PageServerLoad = async ({ locals, url }) => {\n\tawait requireAdmin({ locals } as RequestEvent);\n\n\tconst { limit, offset } = parsePagination(url.searchParams);\n\tconst action = url.searchParams.get('action') ?? undefined;\n\tconst entityType = url.searchParams.get('entityType') ?? undefined;\n\n\tconst entries = await audit.list({ limit, offset, action, entityType });\n\treturn { entries, limit, offset };\n};\n",
